const items = $input.all();
const today = new Date();
const endDate = today.toISOString().split('T')[0];
const start = new Date(today.getTime() - 28 * 24 * 60 * 60 * 1000);
const startDate = start.toISOString().split('T')[0];
const articles = items
  .map(i => i.json)
  .filter(r => r['URL publiée'] && String(r['URL publiée']).startsWith('http'));
if (articles.length === 0) {
  throw new Error('Aucun article avec URL publiée dans DASHBOARD. Ajoute des URLs dans la colonne "URL publiée".');
}
return [{ json: { articles, startDate, endDate, total: articles.length } }];

const prev = $input.first().json;
const siteUrl = 'https://schoolswp.com/';
const encodedSite = encodeURIComponent(siteUrl);
const gscQuery = {
  startDate: prev.startDate,
  endDate: prev.endDate,
  dimensions: ['page'],
  rowLimit: 25000,
  startRow: 0
};
const gscUrl = `https://searchconsole.googleapis.com/webmasters/v3/sites/${encodedSite}/searchAnalytics/query`;
return [{ json: { ...prev, gscQuery, gscUrl } }];

const prev = $('Code - Build GSC Query').first().json;
const gscRaw = $input.first().json;

// Build GSC map : URL → metrics
const gscMap = {};
if (gscRaw.rows && Array.isArray(gscRaw.rows)) {
  for (const row of gscRaw.rows) {
    const url = (row.keys && row.keys[0]) || '';
    if (url) {
      gscMap[url] = {
        clics: Math.round(row.clicks || 0),
        impressions: Math.round(row.impressions || 0),
        ctr: Math.round((row.ctr || 0) * 1000) / 10,
        position: Math.round((row.position || 0) * 10) / 10
      };
    }
  }
}

// Compute Score Global + GSC enrichment for each article
const results = prev.articles.map(article => {
  const url = article['URL publiée'] || '';
  const gsc = gscMap[url] || {};

  const scoreSeo = parseFloat(article['Score SEO']) || 0;
  const scoreConv = parseFloat(article['Score Conversion']) || 0;
  const scoreAuth = parseFloat(article['Score Autorité']) || 0;
  const llmScore = parseFloat(article['LLM Score']) || 50;

  // SEO réel = composite internal + GSC signals
  const ctrBonus = gsc.ctr ? Math.min(100, Math.round((gsc.ctr / 4) * 100)) : 0;
  const posBonus = gsc.position > 0 ? Math.max(0, Math.round(110 - (gsc.position * 5.5))) : 0;
  const seoReal = gsc.position > 0
    ? Math.round((scoreSeo + ctrBonus + posBonus) / 3)
    : scoreSeo;

  // Score Global = SEO×25% + LLM×15% + Conversion×30% + Autorité×30%
  const scoreGlobal = Math.round(
    (seoReal * 0.25) +
    (llmScore * 0.15) +
    (scoreConv * 0.30) +
    (scoreAuth * 0.30)
  );

  const action = scoreGlobal >= 95 ? '✅ Actif premium'
    : scoreGlobal >= 85 ? '🟢 Actif performant'
    : scoreGlobal >= 70 ? '🟡 Optimiser'
    : '🔴 Révision stratégique';

  const aiOverview = article['AI Overview'] === 'oui' ? 100 : article['AI Overview'] === 'non' ? 0 : 50;
  const citationLLM = article['Citation LLM'] === 'oui' ? 100 : article['Citation LLM'] === 'non' ? 0 : 50;
  const llmComputed = Math.round((aiOverview + citationLLM) / 2);

  return {
    'Mot-clé': article['Mot-clé'] || '',
    'Sujet': article['Sujet'] || '',
    'URL publiée': url,
    'Type': article['Type'] || '',
    'Pilier': article['Pilier'] || '',
    'Score SEO': scoreSeo,
    'Score Conversion': scoreConv,
    'Score Autorité': scoreAuth,
    'LLM Score': llmComputed || llmScore,
    'Score Global': scoreGlobal,
    'Action': action,
    '[GSC] Position': gsc.position || '',
    '[GSC] CTR %': gsc.ctr || 0,
    '[GSC] Impressions': gsc.impressions || 0,
    '[GSC] Clics': gsc.clics || 0,
    'Dernière MAJ': prev.endDate,
    'Lien Google Doc': article['Lien Google Doc'] || ''
  };
});

return results.map(r => ({ json: r }));

const articles = $('Code - Parse GSC + Compute Scores').all().map(i => i.json);
const week = $('Code - Build GSC Query').first().json.endDate;

// Sort by Score Global
const sorted = [...articles].sort((a, b) => (b['Score Global'] || 0) - (a['Score Global'] || 0));
const top5 = sorted.slice(0, 5);
const alerts = articles.filter(a => (a['Score Global'] || 0) < 70);
const needsOpt = articles.filter(a => { const s = a['Score Global'] || 0; return s >= 70 && s < 85; });
const premium = articles.filter(a => (a['Score Global'] || 0) >= 85);

// Cluster aggregation
const clusters = {};
for (const a of articles) {
  const pilier = a['Pilier'] || 'Non classé';
  if (!clusters[pilier]) clusters[pilier] = { count: 0, totalScore: 0, totalClics: 0 };
  clusters[pilier].count++;
  clusters[pilier].totalScore += a['Score Global'] || 0;
  clusters[pilier].totalClics += a['[GSC] Clics'] || 0;
}
const clusterLines = Object.entries(clusters)
  .sort((a, b) => b[1].totalClics - a[1].totalClics)
  .map(([pilier, d]) =>
    `*${pilier}* : ${d.count} articles · Score moy ${Math.round(d.totalScore / d.count)}/100 · ${d.totalClics} clics/28j`
  ).join('\n');

const top5Lines = top5.map((a, i) =>
  `${i + 1}. *${a['Mot-clé']}* — ${a['Score Global']}/100 | Pos ${a['[GSC] Position'] || '—'} | CTR ${a['[GSC] CTR %'] || 0}% | ${a['[GSC] Clics'] || 0} clics`
).join('\n');

const alertLines = alerts.length > 0
  ? alerts.slice(0, 5).map(a => `🔴 *${a['Mot-clé']}* — ${a['Score Global']}/100 → ${a['Action']}`).join('\n')
  : '✅ Aucun article en alerte cette semaine.';

const optLines = needsOpt.length > 0
  ? needsOpt.slice(0, 5).map(a => `🟡 *${a['Mot-clé']}* — ${a['Score Global']}/100`).join('\n')
  : '✅ Aucun article à optimiser.';

const totalClics = articles.reduce((s, a) => s + (a['[GSC] Clics'] || 0), 0);
const avgGlobal = Math.round(articles.reduce((s, a) => s + (a['Score Global'] || 0), 0) / (articles.length || 1));

const slackPayload = {
  text: `📊 schoolsWP KPI — semaine du ${week}`,
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: `📊 schoolsWP — KPI Dashboard (${week})` }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Articles analysés*\n${articles.length}` },
        { type: 'mrkdwn', text: `*Score Global moyen*\n${avgGlobal}/100` },
        { type: 'mrkdwn', text: `*Clics organiques (28j)*\n${totalClics}` },
        { type: 'mrkdwn', text: `*Actifs premium (≥85)*\n${premium.length}` }
      ]
    },
    { type: 'divider' },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*🏆 Top 5 articles :*\n${top5Lines}` }
    },
    { type: 'divider' },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*📦 Par pilier :*\n${clusterLines || '—'}` }
    },
    { type: 'divider' },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*🔴 Alertes (Score < 70) :*\n${alertLines}` }
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `*🟡 À optimiser (70–84) :*\n${optLines}` }
    }
  ]
};
return [{ json: { slackPayload, totalArticles: articles.length, alerts: alerts.length, avgGlobal } }];
